import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
const bg=Color(0xFF070B1C), panel=Color(0xFF111936), purple=Color(0xFF7654FF), cyan=Color(0xFF28D7E5);
void main()=>runApp(const Aadati());
class Habit{Habit(this.name,this.icon,{this.done=false});String name;IconData icon;bool done;Map<String,dynamic> toJson()=>{'name':name,'icon':icon.codePoint,'done':done};factory Habit.fromJson(Map<String,dynamic> j)=>Habit(j['name'],IconData(j['icon']??Icons.star.codePoint,fontFamily:'MaterialIcons'),done:j['done']??false);}
class Aadati extends StatelessWidget{const Aadati({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'عاداتي',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,scaffoldBackgroundColor:bg,colorScheme:ColorScheme.fromSeed(seedColor:purple,brightness:Brightness.dark)),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{List<Habit> habits=[];int tab=0;bool loading=true;
@override void initState(){super.initState();load();}
Future<void> load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('habits');if(raw!=null){try{habits=(jsonDecode(raw) as List).map((e)=>Habit.fromJson(Map<String,dynamic>.from(e))).toList();}catch(_){}}if(habits.isEmpty)habits=[Habit('الصلاة في وقتها',Icons.nightlight_round),Habit('قراءة القرآن',Icons.menu_book_rounded),Habit('ممارسة الرياضة',Icons.fitness_center_rounded),Habit('شرب الماء',Icons.water_drop_rounded),Habit('ترتيب الوقت',Icons.auto_awesome_rounded)];if(mounted)setState(()=>loading=false);}
Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('habits',jsonEncode(habits.map((h)=>h.toJson()).toList()));}
int get done=>habits.where((h)=>h.done).length;double get progress=>habits.isEmpty?0:done/habits.length;
Future<void> add()async{final c=TextEditingController();final n=await showDialog<String>(context:context,builder:(x)=>AlertDialog(backgroundColor:const Color(0xFF172247),title:const Text('إضافة عادة'),content:TextField(controller:c,autofocus:true,textDirection:TextDirection.rtl,decoration:const InputDecoration(hintText:'مثال: قراءة 10 صفحات')),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(x,c.text.trim()),child:const Text('إضافة'))]));if(n!=null&&n.isNotEmpty){setState(()=>habits.add(Habit(n,Icons.flag_rounded)));await save();}}
@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));final pages=[dashboard(),habitPage(),stats(),profile()];return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(backgroundColor:bg,title:const Row(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.spa_rounded,color:cyan),SizedBox(width:8),Text('عاداتي',style:TextStyle(fontWeight:FontWeight.bold))]),actions:[IconButton(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('التذكيرات ستضاف لاحقاً'))),icon:const Icon(Icons.notifications_none_rounded))]),body:SafeArea(child:pages[tab]),floatingActionButton:tab<2?FloatingActionButton(onPressed:add,backgroundColor:purple,child:const Icon(Icons.add_rounded)):null,bottomNavigationBar:NavigationBar(backgroundColor:const Color(0xFF0D142B),indicatorColor:purple.withOpacity(.25),selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_rounded),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.check_circle_outline),label:'عاداتي'),NavigationDestination(icon:Icon(Icons.bar_chart_rounded),label:'الإحصائيات'),NavigationDestination(icon:Icon(Icons.person_outline),label:'حسابي')])));}
