Widget habitPage()=>ListView(padding:const EdgeInsets.all(18),children:[const Text('عاداتي اليومية',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('اضغط مطولاً على العادة لحذفها',style:TextStyle(color:Colors.white54)),const SizedBox(height:16),...habits.map(tile),OutlinedButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('إضافة عادة'))]);
Widget tile(Habit h)=>Container(margin:const EdgeInsets.only(bottom:10),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(18),border:Border.all(color:h.done?cyan.withOpacity(.3):Colors.white.withOpacity(.04))),child:ListTile(onLongPress:()async{setState(()=>habits.remove(h));await save();},leading:Container(width:44,height:44,decoration:BoxDecoration(color:purple.withOpacity(.18),borderRadius:BorderRadius.circular(14)),child:Icon(h.icon,color:const Color(0xFFB7A6FF))),title:Text(h.name,style:TextStyle(fontWeight:FontWeight.w600,decoration:h.done?TextDecoration.lineThrough:null)),subtitle:Text(h.done?'أُنجزت اليوم ✓':'خطوة صغيرة نحو هدفك',style:const TextStyle(color:Colors.white54,fontSize:12)),trailing:Checkbox(value:h.done,activeColor:cyan,onChanged:(v)async{setState(()=>h.done=v??false);await save();})));
Widget stats()=>ListView(padding:const EdgeInsets.all(18),children:[const Text('إحصائياتك',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:18),stat('عدد العادات',habits.length.toString(),Icons.track_changes,purple),stat('إنجاز اليوم',done.toString(),Icons.check_circle,cyan),stat('نسبة الإنجاز',(progress*100).round().toString()+'%',Icons.insights,const Color(0xFFFFB454)),const SizedBox(height:10),...habits.map((h)=>Padding(padding:const EdgeInsets.only(bottom:14),child:Column(children:[Row(children:[Expanded(child:Text(h.name)),Text(h.done?'مكتملة':'لم تكتمل',style:const TextStyle(color:Colors.white54))]),const SizedBox(height:7),LinearProgressIndicator(value:h.done?1:0,color:cyan,backgroundColor:panel,minHeight:6)])))]);
